message.content:
这是第 3 页幻灯片，按大纲展示“产品能力”下的三项明确功能：工单归类、责任人分派、状态追踪，并单独标注资料未涵盖的能力说明。整体延续暖米色纸感与细线卡片风格，适合企业内部测评场景使用。
```html
<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"/>
<style>
  *{box-sizing:border-box;}
  html,body{margin:0;padding:0;overflow:hidden;background:#F5F2E9;}
  :root{
    --theme-bg:#F5F2E9;
    --theme-surface:#F3F0E7;
    --theme-ink:#1B2620;
    --theme-muted:#5C665D;
    --theme-accent-primary:#4F5E43;
    --theme-accent-secondary:#B4914A;
    --theme-accent-tertiary:#8C9FB2;
    --theme-line:#A3AC9E;
    --font-display:"Songti SC","Source Han Serif SC","Noto Serif CJK SC",Georgia,"Times New Roman",serif;
    --font-body:"PingFang SC","Hiragino Sans GB","Microsoft YaHei","Source Han Sans SC","Noto Sans CJK SC",Helvetica,Arial,sans-serif;
  }
  .slide{
    position:relative;
    width:1920px;height:1080px;overflow:hidden;
    background:var(--theme-bg);
    font-family:var(--font-body);
    color:var(--theme-ink);
  }
  /* ---------- background field ---------- */
  .bg-field{
    position:absolute;inset:0;z-index:0;
    background:
      radial-gradient(1100px 780px at 2% 0%,rgba(180,145,74,.09),transparent 70%),
      radial-gradient(880px 760px at 47% 46%,rgba(140,159,178,.10),transparent 70%),
      radial-gradient(950px 760px at 95% 95%,rgba(79,94,67,.10),transparent 72%),
      linear-gradient(168deg,#F8F5EC 0%,#F5F2E9 52%,#EFECE1 100%);
  }
  .bg-field:after{
    content:"";position:absolute;inset:0;
    background:repeating-linear-gradient(90deg,rgba(27,38,32,.045) 0 1px,transparent 1px 160px);
    opacity:.9;
  }
  .dot-field{
    position:absolute;z-index:1;opacity:.30;
    background-image:radial-gradient(circle,rgba(27,38,32,.45) 1.05px,transparent 1.15px);
    background-size:15px 15px;
  }
  .dot-a{left:1180px;top:0;width:520px;height:120px;}
  .dot-b{left:640px;top:940px;width:900px;height:140px;opacity:.18;}
  .gridline{position:absolute;z-index:1;width:1px;height:1080px;background:rgba(27,38,32,.05);}
  .gl1{left:480px;}.gl2{left:960px;}.gl3{left:1440px;}
  .soft-prism{
    position:absolute;z-index:1;left:700px;top:-300px;width:150px;height:1500px;
    transform:rotate(17deg);
    background:linear-gradient(180deg,rgba(140,159,178,.20),rgba(140,159,178,.07) 72%,rgba(140,159,178,0));
  }
  .soft-prism:after{
    content:"";position:absolute;left:84px;top:0;width:64px;height:1500px;background:rgba(255,255,255,.35);
  }
  /* ---------- chrome ---------- */
  .top-rule{position:absolute;left:96px;top:48px;width:1760px;height:1px;z-index:6;background:rgba(27,38,32,.34);}
  .left-rule{position:absolute;left:60px;top:40px;width:1px;height:1000px;z-index:6;background:rgba(27,38,32,.24);}
  .rail-label{
    position:absolute;left:44px;top:560px;width:420px;z-index:7;
    transform:rotate(-90deg);transform-origin:left top;
    font-size:13px;font-weight:600;letter-spacing:5px;color:#637067;white-space:nowrap;
  }
  .rail-tick{position:absolute;left:54px;width:13px;height:1px;z-index:7;background:rgba(27,38,32,.42);}
  .rail-tick.t1{top:300px;}.rail-tick.t2{top:760px;}.rail-tick.t3{top:104px;}
  .register{position:absolute;right:-70px;top:-80px;width:280px;height:280px;z-index:2;border-radius:50%;border:1px solid rgba(27,38,32,.30);}
  .register .r2{position:absolute;inset:12px;border-radius:50%;border:1px solid rgba(27,38,32,.16);}
  .register .r3{position:absolute;inset:28px;border-radius:50%;
    background:conic-gradient(from 210deg,rgba(79,94,67,.18),rgba(79,94,67,0) 24%,rgba(140,159,178,.28) 50%,rgba(140,159,178,.07) 78%,rgba(79,94,67,.18));}
  .register .r4{position:absolute;inset:40px;border-radius:50%;background:rgba(245,242,233,.9);border:1px solid rgba(27,38,32,.07);}
  .register .dot{position:absolute;left:52px;top:178px;width:13px;height:13px;border-radius:50%;background:var(--theme-accent-secondary);box-shadow:0 0 0 5px rgba(180,145,74,.13);}
  .edge-prism{position:absolute;z-index:2;left:1876px;top:220px;width:200px;height:1000px;transform:rotate(15deg);transform-origin:top left;opacity:.85;}
  .edge-prism .p1{position:absolute;left:0;top:0;width:56px;height:1000px;background:rgba(140,159,178,.18);}
  .edge-prism .p2{position:absolute;left:78px;top:0;width:34px;height:1000px;background:rgba(79,94,67,.10);}
  /* ---------- header ---------- */
  .top-meta{
    position:absolute;left:98px;top:62px;z-index:15;
    font-size:15px;font-weight:600;letter-spacing:4.2px;color:#4f5b53;
  }
  .top-right-meta{
    position:absolute;right:96px;top:62px;z-index:15;
    font-size:15px;font-weight:600;letter-spacing:3.4px;color:#6b756c;
  }
  .page-title{
    position:absolute;left:96px;top:140px;z-index:15;margin:0;
    font-family:var(--font-display);
    font-size:84px;font-weight:700;line-height:1.08;letter-spacing:2px;
    color:#182219;
  }
  .page-title .bar{color:var(--theme-accent-secondary);font-weight:400;padding:0 6px;}
  .title-underline{
    position:absolute;left:96px;top:288px;z-index:15;width:140px;height:3px;
    background:linear-gradient(90deg,var(--theme-accent-secondary),rgba(180,145,74,0));
  }
  .page-lead{
    position:absolute;left:270px;top:272px;z-index:15;
    font-size:22px;line-height:1.6;color:#5C665D;letter-spacing:.6px;
  }
  /* ---------- capability cards ---------- */
  .cards{
    position:absolute;left:96px;top:346px;width:1760px;height:392px;z-index:12;
    display:flex;gap:44px;
  }
  .cap{
    position:relative;flex:1 1 0;height:100%;
    background:rgba(243,240,231,.78);
    border:1px solid rgba(27,38,32,.17);
    padding:40px 40px 34px;
    display:flex;flex-direction:column;
    overflow:hidden;
  }
  .cap::before{
    content:"";position:absolute;left:0;top:0;width:100%;height:5px;background:var(--acc);
  }
  .cap-glyph{
    position:absolute;right:-46px;top:-46px;width:170px;height:170px;border-radius:50%;
    border:1px solid rgba(27,38,32,.13);
  }
  .cap-glyph:after{
    content:"";position:absolute;inset:22px;border-radius:50%;border:1px solid rgba(27,38,32,.09);
  }
  .cap-idx{
    position:relative;z-index:2;
    font-family:var(--font-display);
    font-size:70px;font-weight:700;line-height:1;
    color:var(--acc);opacity:.42;letter-spacing:1px;
  }
  .cap-title{
    position:relative;z-index:2;margin:26px 0 0;
    font-size:40px;font-weight:700;letter-spacing:1.5px;color:#182219;
  }
  .cap-rule{
    position:relative;z-index:2;margin:24px 0 22px;width:56px;height:2px;background:var(--acc);opacity:.75;
  }
  .cap-desc{
    position:relative;z-index:2;margin:0;
    font-size:23px;line-height:1.75;color:#4E5851;letter-spacing:.5px;
  }
  .cap1{--acc:#4F5E43;}
  .cap2{--acc:#B4914A;}
  .cap3{--acc:#8C9FB2;}
  /* ---------- boundary note ---------- */
  .note{
    position:absolute;left:96px;top:786px;width:1760px;height:132px;z-index:12;
    background:rgba(79,94,67,.075);
    border-left:5px solid var(--theme-accent-secondary);
    border-top:1px solid rgba(27,38,32,.10);
    border-right:1px solid rgba(27,38,32,.10);
    border-bottom:1px solid rgba(27,38,32,.10);
    padding:26px 40px;
    display:flex;align-items:center;gap:38px;
  }
  .note-label{
    flex:0 0 auto;
    font-size:15px;font-weight:700;letter-spacing:4px;color:#7d6226;
    padding:8px 16px;border:1px solid rgba(180,145,74,.55);
    background:rgba(180,145,74,.10);white-space:nowrap;
  }
  .note-text{
    font-size:23px;line-height:1.6;color:#3E4842;letter-spacing:.4px;
  }
  .note-text em{font-style:normal;font-weight:700;color:#25301F;}
  /* ---------- footer ---------- */
  .bottom-rule{position:absolute;left:96px;top:952px;width:1760px;height:1px;z-index:12;background:rgba(27,38,32,.22);}
  .footnote{
    position:absolute;left:96px;top:974px;z-index:15;
    font-size:15px;letter-spacing:1.4px;color:#6E786F;
  }
  .page-no{
    position:absolute;right:96px;top:970px;z-index:15;
    font-size:16px;font-weight:600;letter-spacing:3px;color:#4f5b53;
  }
</style>
</head>
<body>
<main class="slide">
  <div class="bg-field"></div>
  <div class="dot-field dot-a"></div>
  <div class="dot-field dot-b"></div>
  <div class="gridline gl1"></div>
  <div class="gridline gl2"></div>
  <div class="gridline gl3"></div>
  <div class="soft-prism"></div>
  <div class="register">
    <div class="r2"></div>
    <div class="r3"></div>
    <div class="r4"></div>
    <div class="dot"></div>
  </div>
  <div class="edge-prism"><span class="p1"></span><span class="p2"></span></div>

  <div class="top-rule"></div>
  <div class="left-rule"></div>
  <div class="rail-tick t1"></div>
  <div class="rail-tick t2"></div>
  <div class="rail-tick t3"></div>
  <div class="rail-label">澄图工单云 · 企业市场与客户成功团队</div>

  <div class="top-meta">澄图工单云 · 产品能力</div>
  <div class="top-right-meta">测评材料 · 内部使用</div>

  <h1 class="page-title">产品能力<span class="bar">｜</span>三项明确功能</h1>
  <div class="title-underline"></div>
  <div class="page-lead">资料中明确记载的产品功能共三项</div>

  <section class="cards">
    <article class="cap cap1">
      <div class="cap-glyph"></div>
      <div class="cap-idx">01</div>
      <h2 class="cap-title">工单归类</h2>
      <div class="cap-rule"></div>
      <p class="cap-desc">对工单进行分类整理</p>
    </article>

    <article class="cap cap2">
      <div class="cap-glyph"></div>
      <div class="cap-idx">02</div>
      <h2 class="cap-title">责任人分派</h2>
      <div class="cap-rule"></div>
      <p class="cap-desc">为工单指定处理责任人</p>
    </article>

    <article class="cap cap3">
      <div class="cap-glyph"></div>
      <div class="cap-idx">03</div>
      <h2 class="cap-title">状态追踪</h2>
      <div class="cap-rule"></div>
      <p class="cap-desc">跟踪工单处理状态</p>
    </article>
  </section>

  <aside class="note">
    <div class="note-label">资料边界</div>
    <div class="note-text">资料中仅明确<em>这三项功能</em>，未包含集成、SLA 或自动化等能力说明。</div>
  </aside>

  <div class="bottom-rule"></div>
  <div class="footnote">本页为虚构测评材料，内容仅取自资料记载</div>
  <div class="page-no">3 / 6</div>
</main>
</body>
</html>
```
